steps.seedCode:
import React, { useEffect } from 'react';

// Create the SideEffectDemo component here
const SideEffectDemo = () => {
  // Initialize count state here
  const [count, setCount] = React.useState<number>(0);
  // Initialize message state here
  const [message, setMessage] = React.useState<string>('');

  // Create handleIncrement function here
  const handleIncrement = () => {
    setCount(count + 1);
  };

  // Add useEffect with empty dependency array here
  useEffect(() => {
    setMessage('Component mounted!');
  }, []);

  // Add useEffect that depends on count state here
  useEffect(() => {
    if (count > 0) {
      setMessage(`Count updated to: ${count}`);
    }
  }, [count]);

  // Add a cleanup useEffect here

  return (
    <div>
      <h1>useEffect & Side Effects</h1>
      <p>Current count: {count}</p>
      <p>Message: {message}</p>
      <button onClick={handleIncrement}>Increment</button>
    </div>
  );
};

export default SideEffectDemo;
